using System;using System.Collections.Generic;using System.Reflection;using HarmonyLib;using RimWorld;using UnityEngine;using Verse;using Verse.AI;
namespace ElementalHearts {
 public static class CloudStep {
  public const int Cooldown=60;
  static readonly FieldInfo CurrentPath=AccessTools.Field(typeof(Pawn_PathFollower),"curPath"),EndMode=AccessTools.Field(typeof(Pawn_PathFollower),"peMode");
  public static Texture2D Icon(bool travel){return ContentFinder<Texture2D>.Get("UI/Commands/ElementalHearts/TempestIncarnate/"+(travel?"TempestTravel":"CloudStep"));}
  public static string Problem(Pawn p){if(p==null||!TempestIncarnate.Active(p)||!p.Spawned||!ElementalTeaching.Ready(p)||!ElementalCombatPolicy.Controlled(p))return "Requires a conscious player-controlled Tempest Incarnate on a map.";if(TempestIncarnate.Busy(p)||ElementalAnimationBridge.ExternallyControlled(p)||ElementalTeachingSession.Busy(p)||ElementalBestow.Busy(p)||HediffComp_ElementalTransform.Transforming(p)||AzureEvolution.Evolving(p))return "Finish the current action first.";return null;}
  public static bool Safe(Pawn p,IntVec3 cell){if(p==null||!p.Spawned||!cell.InBounds(p.Map)||!cell.Standable(p.Map)||cell.GetTerrain(p.Map).passability==Traversability.Impassable)return false;var door=cell.GetEdifice(p.Map) as Building_Door;if(door!=null&&!door.Open)return false;foreach(var thing in cell.GetThingList(p.Map))if(thing is Pawn||thing is Fire||thing is Building_Trap)return false;return true;}
  public static bool Jump(Pawn p,IntVec3 cell,bool automatic=false){var c=HediffComp_TempestIncarnate.On(p);int now=Find.TickManager.TicksGame;if(c==null||Problem(p)!=null||now<c.stepReadyAt||cell==p.Position||!Safe(p,cell))return false;
   bool preserve=automatic||p.carryTracker!=null&&p.carryTracker.CarriedThing!=null;bool moving=preserve&&p.pather.Moving;var destination=moving?p.pather.Destination:LocalTargetInfo.Invalid;var end=moving&&EndMode!=null?(PathEndMode)EndMode.GetValue(p.pather):PathEndMode.OnCell;var map=p.Map;var from=p.Position.ToVector3Shifted();
   c.stepReadyAt=now+Cooldown;p.Position=cell;p.Notify_Teleported(!preserve,true);foreach(var near in GenRadial.RadialCellsAround(cell,1.5f,true))if(near.InBounds(map))map.fogGrid.Unfog(near);if(moving&&destination.IsValid)p.pather.StartPath(destination,end);
   TempestVfx.Step(p,map,from,cell.ToVector3Shifted());TempestVfx.Track(p);return true;
  }
  public static void BeginManual(Pawn p){if(Problem(p)!=null)return;var map=p.Map;var target=TargetingParameters.ForCell();target.validator=t=>p.Spawned&&p.Map==map&&Find.CurrentMap==map&&Safe(p,t.Cell);Find.Targeter.BeginTargeting(target,t=>{if(!Jump(p,t.Cell))Messages.Message("Cloud Step needs an empty walkable cell and its one-second recharge.",MessageTypeDefOf.RejectInput,false);},t=>{if(t.Cell.InBounds(map))GenDraw.DrawFieldEdges(new List<IntVec3>{t.Cell},Safe(p,t.Cell)?Color.yellow:Color.red);},null,p,null,Icon(false),true);}
  public static void Tick(HediffComp_TempestIncarnate c){var p=c.Pawn;int now=Find.TickManager.TicksGame;if(now<c.nextStepCheck)return;c.nextStepCheck=now+15;if(!c.autoStep||c.thunderTravelMode||now<c.stepReadyAt||Problem(p)!=null||p.pather==null||!p.pather.Moving||p.stances.FullBodyBusy||CurrentPath==null)return;var path=CurrentPath.GetValue(p.pather) as PawnPath;if(path==null||!path.Found)return;int limit=Math.Min(512,path.NodesLeftCount);for(int i=0;i<limit;i++){var cell=path.NodesReversed[i];if(p.Position.DistanceToSquared(cell)<9||!Safe(p,cell))continue;Jump(p,cell,true);return;}}
  public static Command Command(Pawn p){var c=HediffComp_TempestIncarnate.On(p);return new Command_TempestTraversal{pawn=p,defaultLabel=c.thunderTravelMode?"Tempest Travel":"Cloud Step: "+(c.autoStep?"Auto":"Manual"),defaultDesc="Right-click cycles Step: Auto, Step: Manual (automatic stepping off), then Tempest Travel (automatic stepping off).\nCloud Step: left-click toggles Auto/Manual; Shift + left-click chooses an instant map jump. No sight, fog or range limit; the destination must be empty and walkable. One-second recharge, no resource cost. Auto follows movement/work routes and preserves jobs and carried passengers. Its toggle is independent of Auto Combat.\nTempest Travel: choose a clear outdoor launch site, then people, animals and supplies in the familiar loading menu. The carrier stays manifested; companions gather at that site. Available colonists haul cargo, or the carrier gathers it and returns to the site when no helper is free. Select the carrier and press Launch when ready; Travel again edits the manifest. Departure and arrival use elemental effects, with no physical pod. Settlement visits, center/edge/chosen-cell attacks and ISEKAI Tower floor choices are preserved. Free travel, no fuel or cooldown. Shift-click Travel opens the same preparation menu.\nAutomatic map stepping is currently "+(c.autoStep?"on.":"off."),icon=Icon(c.thunderTravelMode),groupable=false,action=()=>{var current=HediffComp_TempestIncarnate.On(p);if(current==null)return;if(current.thunderTravelMode)CelestialLightTravel.Begin(p);else current.autoStep=!current.autoStep;}};}
 }
 public sealed class Command_TempestTraversal:Command_Action {
  public Pawn pawn;
  public void SwitchMode(){var c=HediffComp_TempestIncarnate.On(pawn);if(c==null)return;if(c.thunderTravelMode){c.thunderTravelMode=false;c.autoStep=true;}else if(c.autoStep)c.autoStep=false;else{c.thunderTravelMode=true;c.autoStep=false;}defaultLabel=c.thunderTravelMode?"Tempest Travel":"Cloud Step: "+(c.autoStep?"Auto":"Manual");icon=CloudStep.Icon(c.thunderTravelMode);}
  protected override GizmoResult GizmoOnGUIInt(Rect rect,GizmoRenderParms parms){var ev=Event.current;if(ev.type==EventType.MouseDown&&ev.button==1&&rect.Contains(ev.mousePosition)){SwitchMode();ev.Use();}return base.GizmoOnGUIInt(rect,parms);}
  public override void ProcessInput(Event ev){var c=HediffComp_TempestIncarnate.On(pawn);if(c!=null&&ev.shift){if(c.thunderTravelMode)CelestialLightTravel.Begin(pawn,false);else CloudStep.BeginManual(pawn);return;}base.ProcessInput(ev);}
 }
}
